const memoryCache = new Map();

// Synchronously returns precomputed/cached road-snapped coordinates with 0ms latency
export const getSyncRoadGeometry = (stops, busIdentifier = '', direction = 'forward') => {
  if (!stops || stops.length < 2) return null;

  const bKey = String(busIdentifier || '').toUpperCase().trim();
  const dir = direction === 'return' ? 'return' : 'forward';

  // 1. Instant check for known corridors (14A, 32C, 43C)
  let baseCoords = null;
  const firstStopName = (stops[0]?.name || '').toLowerCase();
  const lastStopName = (stops[stops.length - 1]?.name || '').toLowerCase();

  if (bKey.includes('14A') || firstStopName.includes('vadukatchi') || lastStopName.includes('vadukatchi')) {
    baseCoords = PRECOMPUTED_CORRIDOR_GEOMETRY['14A'];
  } else if (bKey.includes('32C') || firstStopName.includes('parappadi') || lastStopName.includes('parappadi')) {
    baseCoords = PRECOMPUTED_CORRIDOR_GEOMETRY['32C'];
  } else if (bKey.includes('43C') || firstStopName.includes('town') || lastStopName.includes('town') || firstStopName.includes('tirunelveli') || lastStopName.includes('tirunelveli')) {
    baseCoords = PRECOMPUTED_CORRIDOR_GEOMETRY['43C'];
  }

  if (baseCoords && baseCoords.length > 0) {
    const pStartLat = Number(stops[0].lat);
    const pStartLng = Number(stops[0].lng);
    const distToFirst = Math.hypot(pStartLat - baseCoords[0][0], pStartLng - baseCoords[0][1]);
    const distToLast = Math.hypot(pStartLat - baseCoords[baseCoords.length - 1][0], pStartLng - baseCoords[baseCoords.length - 1][1]);

    if (distToLast < distToFirst || dir === 'return') {
      return [...baseCoords].reverse();
    }
    return [...baseCoords];
  }

  const stopsHash = stops.map(s => `${Number(s.lat).toFixed(4)},${Number(s.lng).toFixed(4)}`).join(';');
  const cacheKey = `road_geom_${dir}_${stopsHash}`;
  if (memoryCache.has(cacheKey)) {
    return memoryCache.get(cacheKey);
  }

  return null;
};

// Returns exact road-snapped coordinates for any bus and any route
export const getRoadGeometry = async (stops, busIdentifier = '', direction = 'forward') => {
  if (!stops || stops.length < 2) return [];

  // 1. Instant synchronous check
  const syncGeom = getSyncRoadGeometry(stops, busIdentifier, direction);
  if (syncGeom && syncGeom.length > 1) {
    return syncGeom;
  }

  const dir = direction === 'return' ? 'return' : 'forward';
  const stopsHash = stops.map(s => `${Number(s.lat).toFixed(4)},${Number(s.lng).toFixed(4)}`).join(';');
  const cacheKey = `road_geom_${dir}_${stopsHash}`;

  try {
    if (typeof sessionStorage !== 'undefined') {
      const sessionCached = sessionStorage.getItem(cacheKey);
      if (sessionCached) {
        const parsed = JSON.parse(sessionCached);
        if (Array.isArray(parsed) && parsed.length > 1) {
          memoryCache.set(cacheKey, parsed);
          return parsed;
        }
      }
    }
  } catch (e) {}

  // 3. For newly created routes, fetch from OSRM with full route and leg fallback
  let fetchedCoords = null;
  try {
    const coordsStr = stops.map(s => `${s.lng},${s.lat}`).join(';');
    const osrmUrl = `https://router.project-osrm.org/route/v1/driving/${coordsStr}?overview=full&geometries=geojson`;
    const res = await fetch(osrmUrl);
    const data = await res.json();
    if (data && (data.code === 'Ok' || (data.routes && data.routes.length > 0))) {
      fetchedCoords = data.routes[0].geometry.coordinates.map(c => [Number(c[1].toFixed(5)), Number(c[0].toFixed(5))]);
    }
  } catch (err) {
    console.warn('Full OSRM query failed, trying leg-by-leg:', err);
  }

  if (!fetchedCoords || fetchedCoords.length < 2) {
    const legCoords = [];
    for (let i = 0; i < stops.length - 1; i++) {
      const p1 = stops[i];
      const p2 = stops[i + 1];
      try {
        const legUrl = `https://router.project-osrm.org/route/v1/driving/${p1.lng},${p1.lat};${p2.lng},${p2.lat}?overview=full&geometries=geojson`;
        const legRes = await fetch(legUrl);
        const legData = await legRes.json();
        if (legData && (legData.code === 'Ok' || (legData.routes && legData.routes.length > 0))) {
          const c = legData.routes[0].geometry.coordinates.map(coord => [Number(coord[1].toFixed(5)), Number(coord[0].toFixed(5))]);
          legCoords.push(...c);
        } else {
          legCoords.push([Number(p1.lat), Number(p1.lng)], [Number(p2.lat), Number(p2.lng)]);
        }
      } catch (e) {
        legCoords.push([Number(p1.lat), Number(p1.lng)], [Number(p2.lat), Number(p2.lng)]);
      }
    }
    if (legCoords.length > 1) {
      fetchedCoords = legCoords;
    }
  }

  // 4. Dense interpolation fallback if completely offline
  if (!fetchedCoords || fetchedCoords.length < 2) {
    const denseFallback = [];
    const SUB_STEPS = 15;
    for (let i = 0; i < stops.length - 1; i++) {
      const p1 = stops[i];
      const p2 = stops[i + 1];
      for (let s = 0; s < SUB_STEPS; s++) {
        const ratio = s / SUB_STEPS;
        denseFallback.push([
          Number((p1.lat + (p2.lat - p1.lat) * ratio).toFixed(5)),
          Number((p1.lng + (p2.lng - p1.lng) * ratio).toFixed(5))
        ]);
      }
    }
    const last = stops[stops.length - 1];
    denseFallback.push([Number(last.lat), Number(last.lng)]);
    fetchedCoords = denseFallback;
  }

  const finalResult = dir === 'return' ? [...fetchedCoords].reverse() : fetchedCoords;
  memoryCache.set(cacheKey, finalResult);
  try {
    if (typeof sessionStorage !== 'undefined') {
      sessionStorage.setItem(cacheKey, JSON.stringify(finalResult));
    }
  } catch (e) {}

  return finalResult;
};

// Generates uniform discrete simulation steps along the exact road coordinates
export const getSimulationPathFromRoad = (roadCoords, stops, direction = 'forward') => {
  if (!roadCoords || roadCoords.length < 2) return [];

  const targetSteps = 120;
  const stepInterval = Math.max(1, Math.floor(roadCoords.length / targetSteps));
  const sampledCoords = [];
  for (let i = 0; i < roadCoords.length; i += stepInterval) {
    sampledCoords.push(roadCoords[i]);
  }
  const lastCoord = roadCoords[roadCoords.length - 1];
  if (sampledCoords[sampledCoords.length - 1] !== lastCoord) {
    sampledCoords.push(lastCoord);
  }

  const destStopName = stops && stops.length > 0 
    ? stops[stops.length - 1].name 
    : (direction === 'forward' ? 'Rohini College Campus (RCET)' : 'Origin');
  const totalMins = Math.max(...(stops || []).map(s => s.estimatedMinutesFromStart || 0), 45);

  const path = [];
  const totalPoints = sampledCoords.length;

  for (let i = 0; i < totalPoints; i++) {
    const curr = sampledCoords[i];
    const next = sampledCoords[Math.min(i + 1, totalPoints - 1)];

    const ratio = i / (totalPoints - 1 || 1);
    const remMins = Math.max(0, Math.round(totalMins * (1 - ratio)));
    const etaText = remMins <= 0 ? `Arrived at ${destStopName}` : `${remMins} mins to ${destStopName}`;

    let heading = 180;
    if (next && (next[0] !== curr[0] || next[1] !== curr[1])) {
      heading = Math.round((Math.atan2(next[1] - curr[1], next[0] - curr[0]) * 180) / Math.PI);
      if (heading < 0) heading += 360;
    }

    path.push({
      lat: curr[0],
      lng: curr[1],
      etaText,
      heading,
      stopName: stops && stops[0] ? stops[0].name : 'Origin'
    });
  }

  return path;
};
